is_password_name(name) {
    regex.match(`(?i)(password|passwd|pwd|passphrase|credential|connection_string|dsn)`, name)
}

is_secret_name(name) {
    regex.match(`(?i)(secret|auth_token)`, name)
}

is_key_name(name) {
    regex.match(`(?i)key$`, name)
}

is_credential_name(name) {
