    val.value == ""
} else {
    val.ir_type == "Null"
} else {
    val.ir_type == "Undef"
}

is_optional_empty_placeholder(name, val) {
    regex.match(`(?i)(cache|example|sample|placeholder|demo)`, name)
    val.ir_type == "String"
    val.value == ""
}

